// Definition for a singly linked list node
class ListNode<T> {
  value: T;
  next: ListNode<T> | null;

  constructor(value: T, next: ListNode<T> | null = null) {
    this.value = value;
    this.next = next;
  }
}

/**
 * Reverses a singly linked list in place.
 * 
 * Uses three pointers to reverse the direction of each link:
 *   - prev: the already-reversed portion (starts as null)
 *   - current: the node currently being processed
 *   - next: temporary storage for the next node before we overwrite the link
 * 
 * Time Complexity: O(n)
 * Space Complexity: O(1)
 */
function reverseLinkedList<T>(head: ListNode<T> | null): ListNode<T> | null {
  let prev: ListNode<T> | null = null;
  let current: ListNode<T> | null = head;

  while (current !== null) {
    const next: ListNode<T> | null = current.next; // 1. Save next node
    current.next = prev;                            // 2. Reverse the link
    prev = current;                                 // 3. Advance prev
    current = next;                                 // 4. Advance current
  }

  return prev; // prev is now the new head
}

// ─── Helper: Convert list to array (for easy display) ────────────────
function toArray<T>(head: ListNode<T> | null): T[] {
  const result: T[] = [];
  let current = head;
  while (current !== null) {
    result.push(current.value);
    current = current.next;
  }
  return result;
}

