    target: T,
    compareFn: (a: T, b: T) => number
): number {
    let left = 0;
    let right = arr.length - 1;

    while (left <= right) {
        const mid = Math.floor(left + (right - left) / 2);
        const comparison = compareFn(arr[mid], target);

        if (comparison === 0) {
            return mid;
        } else if (comparison < 0) {
