function deepClone<T>(source: T): T {
  // Handle null, undefined, and primitive types
  if (source === null || source === undefined || typeof source !== "object") {
    return source;
  }

  // Handle Date
  if (source instanceof Date) {
    return new Date(source.getTime()) as unknown as T;
  }

  // Handle RegExp
  if (source instanceof RegExp) {
    return new RegExp(source.source, source.flags) as unknown as T;
  }

  // Handle Map
  if (source instanceof Map) {
    const clonedMap = new Map();
    source.forEach((value, key) => {
      clonedMap.set(deepClone(key), deepClone(value));
    });
    return clonedMap as unknown as T;
  }

  // Handle Set
  if (source instanceof Set) {
    const clonedSet = new Set();
    source.forEach((value) => {
      clonedSet.add(deepClone(value));
    });
    return clonedSet as unknown as T;
  }

  // Handle Array
  if (Array.isArray(source)) {
    return source.map((item) => deepClone(item)) as unknown as T;
  }

  // Handle plain Objects
  const clonedObj = Object.create(Object.getPrototypeOf(source));
  for (const key of Object.keys(source)) {
    (clonedObj as Record<string, unknown>)[key] = deepClone(
      (source as Record<string, unknown>)[key]
    );
  }

  return clonedObj;
}
```

